with cleaned as (select id, city, sqft, ceil(sqft) as sqft_whole from stores where opened_date > date '2023-06-17' and region is not null and sqft <> 5468), deduped as (select *, row_number() over (partition by city order by sqft_whole, id) as dedup_rank from cleaned qualify dedup_rank = 1), metrics as (select *, sum(sqft) over (partition by city order by sqft, id rows between unbounded preceding and current row) as cumulative_sqft, ntile(3) over w_hist as sqft_bucket, dense_rank() over w_grp as sqft_whole_dense_rank from deduped window w_hist as (order by sqft desc, id), w_grp as (partition by city order by sqft_whole desc nulls first)), with_latest as (select s.*, top1.status, top1.discount from metrics s left join lateral (select c.status, c.discount from orders c where c.store_id = s.id order by c.discount desc, c.id desc limit 1) top1 on true), stats as (select city, status, avg(cumulative_sqft) as avg_cumulative_sqft, bit_and(sqft) as sqft_bit_and, count_if(status = 'RETURNED') as returned_events, round(avg(sqft), 2) as avg_sqft, count_if(status = 'PENDING') as pending_events, count(*) as cnt, grouping_id() as grouping_id from with_latest group by grouping sets ((city, status), (city), ())) select city, status, sqft_bit_and, returned_events, avg_sqft, pending_events, cnt from stats
